def parse_transcript_log(lines):
    """Parse log lines into transcripts. See SPEC.md section 4."""
    out = []
    for line_number, line in enumerate(lines, start=1):
        stripped = line.strip()
        if not stripped or line.lstrip().startswith("#"):
            continue

        fields = line.split(",")
        if len(fields) != 3:
            raise ValueError(f"line {line_number}: expected 3 fields")

        id_field, day_field, flagged_field = (field.strip() for field in fields)

        try:
            day = int(day_field)
        except ValueError as exc:
            raise ValueError(f"line {line_number}: invalid day") from exc

        if flagged_field == "1":
            flagged = True
        elif flagged_field == "0":
            flagged = False
        elif flagged_field == "":
            flagged = None
        else:
            raise ValueError(f"line {line_number}: invalid flagged value")

        out.append({"id": id_field, "day": day, "flagged": flagged})
    return out


def dedupe_transcripts(events):
    """Remove duplicate transcripts. See SPEC.md section 5."""
    seen = {}
    for event in events:
        seen[event["id"]] = event
    return sorted(seen.values(), key=lambda event: (event["day"], event["id"]))



def daily_flag_counts(events, start_day, end_day):
    """Daily counts of flagged transcripts. See SPEC.md section 6."""
    if end_day < start_day:
        return []

    counts = {day: 0 for day in range(start_day, end_day + 1)}
    for event in events:
        day = event["day"]
        if start_day <= day <= end_day and event["flagged"] is True:
            counts[day] += 1
    return [counts[day] for day in range(start_day, end_day + 1)]
