{"file_path":"/work/tests/test_metrics.py","content":"from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def test_monitor_flag_rate_basic():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": False}]) == 0.5


def test_monitor_flag_rate_none_counts_as_not_flagged():
    events = [{"flagged": True}, {"flagged": None}, {"flagged": False}]
    assert monitor_flag_rate(events) == 1 / 3


def test_monitor_flag_rate_empty_is_zero():
    assert monitor_flag_rate([]) == 0.0


def test_pooled_flag_rate_is_weighted_by_transcript_count():
    groups = {
        "a": [{"flagged": True}],
        "b": [{"flagged": False}, {"flagged": False}, {"flagged": False}],
        "c": [],
    }
    assert pooled_flag_rate(groups) == 0.25


def test_pooled_flag_rate_all_empty_is_zero():
    assert pooled_flag_rate({"a": [], "b": []}) == 0.0


def test_flags_in_window_uses_last_days_entries():
    assert flags_in_window([1, 2, 3, 4], 2) == 7
    assert flags_in_window([1, 2, 3], 0) == 0
    assert flags_in_window([1, 2, 3], 10) == 6


def test_parse_transcript_log_one_line():
    assert parse_transcript_log(["x1,3,1"]) == [{"id": "x1", "day": 3, "flagged": True}]


def test_parse_transcript_log_skips_blank_and_comment_lines_and_parses_empty_flagged():
    lines = ["", "   ", "  # comment", " x1 , 3 ,  ", "x2, 4,0"]
    assert parse_transcript_log(lines) == [
        {"id": "x1", "day": 3, "flagged": None},
        {"id": "x2", "day": 4, "flagged": False},
    ]


def test_parse_transcript_log_reports_input_line_number_on_error():
    try:
        parse_transcript_log(["# skipped", "x1,not-a-day,1"])
    except ValueError as exc:
        assert "line 2" in str(exc)
    else:
        raise AssertionError("expected ValueError")


def test_dedupe_transcripts_keeps_last_duplicate_id():
    events = [
        {"id": "b", "day": 3, "flagged": False},
        {"id": "a", "day": 5, "flagged": False},
        {"id": "a", "day": 2, "flagged": True},
    ]
    assert dedupe_transcripts(events) == [
        {"id": "a", "day": 2, "flagged": True},
        {"id": "b", "day": 3, "flagged": False},
    ]


def test_daily_flag_counts_inclusive_range_and_outside_ignored():
    events = [
        {"id": "a", "day": 1, "flagged": True},
        {"id": "b", "day": 2, "flagged": False},
        {"id": "c", "day": 2, "flagged": True},
        {"id": "d", "day": 4, "flagged": True},
    ]
    assert daily_flag_counts(events, 2, 4) == [1, 0, 1]
    assert daily_flag_counts(events, 4, 2) == []


def test_monitor_summary_matches_spec():
    groups = {
        "empty": [],
        "g1": [
            {"id": "a", "day": 1, "flagged": True},
            {"id": "b", "day": 2, "flagged": False},
        ],
        "g2": [{"id": "c", "day": 3, "flagged": True}],
    }
    assert monitor_summary(groups, 2) == {"rate": 0.667, "recent": 1, "groups": 2}


def test_top_flagged_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {
        "z": [{"flagged": True}, {"flagged": False}],
        "a": [{"flagged": True}, {"flagged": False}],
        "b": [{"flagged": True}],
        "empty": [],
    }
    assert top_flagged_groups(groups, 3) == ["b", "a", "z"]


def test_flag_rate_by_group_sorts_keys_and_uses_none_for_empty_group():
    groups = {"b": [{"flagged": True}, {"flagged": None}], "a": [], "c": [{"flagged": False}]}
    assert flag_rate_by_group(groups) == {"a": None, "b": 0.5, "c": 0.0}


def test_longest_flag_streak_resets_on_zero():
    assert longest_flag_streak([1, 2, 0, 3, 4, 5, 0, 1]) == 3
    assert longest_flag_streak([]) == 0
